// Independent hand-computable cases and model invariants. Not browser/visual certification.
import fs from 'node:fs';import vm from 'node:vm';import assert from 'node:assert/strict';
const ctx={};ctx.window=ctx;vm.createContext(ctx);vm.runInContext(fs.readFileSync(new URL('../students/lab-models.js',import.meta.url),'utf8'),ctx);const M=ctx.MT_LABS;
let checks=0;const ok=(x,m)=>{assert.ok(x,m);checks++},near=(a,b,t,m)=>ok(Number.isFinite(a)&&Math.abs(a-b)<=t,m+': '+a+' expected '+b),reject=(fn,m)=>{let threw=false;try{fn()}catch{threw=true}ok(threw,m)};
const input={displacement:10000,kg:7,weight:200,lift:2,length:12,breadth:10,density:1.025,divisions:1};
const s=M.stability(input);
near(s.movedKG,7.04,1e-12,'200 t raised 2 m on 10000 t displacement');near(s.inertia,1000,1e-12,'12 × 10³ / 12 rectangular free surface');near(s.fsm,1025,1e-9,'density × free-surface inertia');near(s.fsc,.1025,1e-12,'FSM / displacement');near(s.gm,1.3575,1e-12,'KM minus relocated KG minus FSC');near(M.kn(0),0,1e-12,'zero heel KN');near(s.gz(0),0,1e-12,'zero heel GZ');near(M.kn(90),3,1e-12,'independent synthetic KN endpoint');near(s.gz(90),-4.1425,1e-12,'large-angle KG sin term');
near(s.gz(.0001)/(.0001*Math.PI/180),s.gm,1e-8,'initial GZ slope equals corrected GM');
near(M.stability({...input,divisions:2}).fsc,s.fsc/4,1e-12,'two isolated equal compartments quarter FSC');near(M.stability({...input,divisions:4}).fsc,s.fsc/16,1e-12,'four compartments divide FSC by sixteen');
near(M.stability({...input,weight:0,density:0}).gm,1.5,1e-12,'zero moment and zero liquid correction');
near(M.stability({...input,lift:-2}).movedKG,6.96,1e-12,'lowering weight lowers KG');ok(s.zero>40&&s.zero<90,'synthetic positive range ends before 90 degrees');
near(s.gz(s.zero),0,.0002,'interpolated zero-crossing residual');
// Independent integration of analytic GZ expression using high-resolution midpoint quadrature.
const end=Math.PI/6,N=20000,d=end/N;let independentArea=0;for(let i=0;i<N;i++){const a=(i+.5)*d,t=Math.sin(a);independentArea+=((8.5-s.effectiveKG)*t+2*t**3-7.5*t**5)*d}near(s.area30,independentArea,.00002,'0–30 degree area uses radians');
reject(()=>M.stability({...input,displacement:0}),'zero displacement rejected');reject(()=>M.stability({...input,weight:11000}),'moving more than ship mass rejected');reject(()=>M.stability({...input,divisions:1.5}),'fractional subdivision rejected');
near(M.scale(5,0,10),12,1e-12,'5 bar is 12 mA');near(M.scale(4,-20,80,true),-20,1e-12,'4 mA is lower range');near(M.scale(20,-20,80,true),80,1e-12,'20 mA is upper range');near(M.scale(12,-20,80,true),30,1e-12,'live-zero offset in nonzero range');
reject(()=>M.scale(3.6,0,10,true),'below nominal range rejected');reject(()=>M.scale(5,10,0),'reversed range rejected');reject(()=>M.scale(NaN,0,10),'NaN process input rejected');
const pidInput={kp:2,ti:20,td:0,tau:20,setpoint:60,direction:'reverse',antiWindup:true},r=M.pid(pidInput);ok(r.length===1801,'180 seconds in 0.1 second samples');near(r[0].pv,20,1e-12,'initial process condition');near(r[99].sp,20,1e-12,'no setpoint step before 10 seconds');near(r[100].sp,60,1e-12,'step at 10 seconds');ok(r.every(p=>Object.values(p).every(Number.isFinite)&&p.u>=0&&p.u<=100),'all PID states finite and output bounded');near(r.at(-1).pv,60,.1,'PI removes steady offset');
const pOnly=M.pid({...pidInput,ti:0});near(pOnly.at(-1).pv,(20+2*60)/3,.01,'P-only analytical closed-loop equilibrium');
const dOnly=M.pid({...pidInput,ti:0,td:5});near(dOnly[100].u,80,1e-12,'derivative on PV avoids setpoint kick');
const direct=M.pid({...pidInput,direction:'direct'});near(direct.at(-1).pv,20,1e-12,'wrong action saturates low for positive-gain process');
reject(()=>M.pid({...pidInput,tau:0}),'invalid process time constant rejected');
const eInput={bore:Math.sqrt(4/Math.PI),stroke:1,cylinders:1,rpm:60,cycles:1,mep:1,basis:'brake',mechanicalEfficiency:.8,brakeEfficiency:.4,lhv:45},e=M.engine(eInput);near(e.volume,1,1e-12,'one cubic metre swept volume');near(e.brake,100,1e-10,'1 bar × 1 m³ × 1 cycle/s = 100 kW');near(e.indicated,125,1e-10,'mechanical efficiency power basis');near(e.thermal,250,1e-10,'100 kW / 0.4 = 250 kW fuel input');near(e.fuel,20,1e-10,'250 kW × 3.6 / 45 MJ/kg = 20 kg/h');near(e.sfoc,200,1e-10,'20 kg/h / 100 kW = 200 g/kWh');near(e.pistonSpeed,2,1e-12,'mean piston speed');near(M.engine({...eInput,cycles:2}).brake,50,1e-10,'four-stroke half cycles at fixed MEP');near(M.engine({...eInput,lhv:22.5}).fuel,40,1e-10,'halving LHV doubles mass at equal efficiency');near(M.engine({...eInput,basis:'indicated'}).brake,80,1e-10,'net IMEP produces indicated power before mechanical losses');reject(()=>M.engine({...eInput,rpm:0}),'zero speed excluded from SFOC model');reject(()=>M.engine({...eInput,cylinders:1.5}),'fractional cylinders rejected');reject(()=>M.engine({...eInput,brakeEfficiency:0}),'zero efficiency rejected');
reject(()=>M.engine({...eInput,mechanicalEfficiency:.2,brakeEfficiency:.4}),'combined efficiencies cannot imply more than 100 percent indicated thermal efficiency');
const read=p=>fs.readFileSync(new URL('../'+p,import.meta.url),'utf8'),html=read('students/labs.html'),sw=read('sw.js');
for(const id of ['stability','controls','engine'])ok(html.includes('id="'+id+'"'),'deep-linked module '+id);
for(const asset of ['labs.html','labs.css','lab-models.js','labs.js'])ok(sw.includes("'./students/"+asset+"'"),'offline shell includes '+asset);
ok(read('students/index.html').includes('href="interactive.html"')&&['labs.html#stability','labs.html#controls','labs.html#engine'].every(url=>read('students/interactive-catalogue-20261030.js').includes(url)),'student entry reaches all three labs through the shared workspace');ok(!/fetch\s*\(|XMLHttpRequest|sendBeacon|eval\s*\(/.test(read('students/labs.js')),'local model with no API calls or dynamic evaluation');
